cd /home/user/RL_Study/report-gepa/runs/originals/spades && python3 - <<'PY'
import json, pandas as pd, numpy as np
for fn in ['facts.json','skipped.json']:
    d=json.load(open(fn)); print(fn, 'OK', len(d), 'entries')
print('\nFACTS')
for f in json.load(open('facts.json')):
    env={'pd':pd,'np':np}
    for k,p in f['tables'].items(): env[k]=pd.read_csv(p)
    v=eval(f['code'],env)
    print('---',f['id']); print(v)
PY
